// Every card-derived order argument is computed BEFORE the save, so a
// throw here happens before anything is written.
const optionSymbol = toOptionSymbol(card);
const limitPrice = orderType === 'LMT' ? entryLimitFor(card) : null;
const pos = buildPaperPosition(card, orderType, broker, 'pending', freshQuote?.price, contracts);
const recId = pos.recId;

// The backend would 409 anyway; refusing locally means a SAVE-UNCONFIRMED
// note can only ever point at a row THIS send created.
if (usePortfolioStore.getState().positions.some((p) => p.contract === pos.contract)) {
  setOrderError(`${label}: No order was sent — a position for this contract is already tracked in Portfolio. Close or edit that one instead.`);
  return;
}

// Audit round 1, F1: the save carries the order it precedes, so the
// server judges the D5 premium cap at what this order can PAY -- the
// edited limit when it is above the mid, the ask for a market order --
// and not at `pos.entryPrice`, the mid it stores. `limitPrice` is the
// very value the order below posts.
const saved = await persistPosition(pos, undefined, { orderType, limitPrice });
// Unconfirmed: offline; a bare gateway 5xx (no JSON detail, so the create
// may still be running); or a 2xx whose body did not parse (the page
// cannot know whether the server resized). No order is sent. The create
// may still commit AFTER a delete lands, so the note is pushed whatever
// the delete answers, and `applyPersistedPosition` is never called here
// (its offline branch would re-POST).
const bare5xx = !saved.ok && !saved.offline && /^HTTP 5\d\d$/.test(saved.detail ?? '');
const unparsed2xx = saved.ok && saved.entryPrice == null;
if (saved.offline || bare5xx || unparsed2xx) {
  setOrderError(unparsed2xx
    ? `${label}: Portfolio saved it but its reply could not be read, so NO order was sent.`
    : `${label}: Portfolio tracking could not be confirmed, so NO order was sent.`);
  addDirectNote({ recId, kind: 'save-unconfirmed', label, brokerLabel, orderId: null });
  dropLocal(recId);
  try { await removeTrackedRow(recId, false); } catch { /* best effort; the note stays */ }
  return;
}
if (!saved.ok) {
  // The server answered no. Every refusal is raised before the commit or
  // after a rollback, so nothing was written: no delete (on a 409 the
  // only matching row is the user's real one), no note.
  const detail = saved.detail ?? 'not saved';
  setOrderError(/already exists/.test(detail)
    ? `${label}: No order was sent — a position for this contract is already tracked in Portfolio. Close or edit that one instead.`
    : `${label}: No order was sent — ${detail.replace(/\.$/, '')}.`);
  return;
}

// Confirmed save. EVERYTHING from here sits in this try/catch: nothing
// after the save may reach the outer catch, which would leave a saved row
// with no note.
const orderQty = saved.adjustedQty ?? contracts;
const keepRow = (why: string, orderId: string | null) => {
  // Note FIRST, row second: a throw can never leave a row without its note.
  addDirectNote({ recId, kind: 'order-unknown', label, brokerLabel, orderId });
  const banner = `${label}: Order status UNKNOWN (${why}).`;
  setOrderError(banner);
  try {
    applyPersistedPosition(
      saved, { ...pos, contracts: orderQty }, addPosition,
      (q) => addSaveNote(`${label}: Portfolio sized it to ${q}; the order was requested for ${q}, status unknown.`),
      (r, why, kept) => addSaveNote(`${label}: ${droppedStopNote(r, why, kept)}`),
    );
  } catch (e) {
    setOrderError(`${banner} The local view failed to update: ${String(e)}`);
  }
};
try {
  let outcome: DirectOutcome;
  try {
    const res = await api.postOptionOrder({
      broker,
      symbol:        card.symbol,
      option_symbol: optionSymbol,
      action:        'BUY',
      effect:        'OPEN',
      quantity:      orderQty,
      order_type:    orderType,
      limit_price:   limitPrice,
      tif:           'DAY',
    });
    outcome = classifyDirectFailure({ response: res });
  } catch (e) {
    outcome = classifyDirectFailure({ thrown: e });
  }

  if (outcome.verdict === 'delete') {
    // Provably never received by the broker: remove the saved row.
    try {
      await removeTrackedRow(recId, true);
      setOrderError(`${label}: Order NOT placed: ${outcome.why}. The tracked position was removed.`);
    } catch {
      setOrderError(`${label}: Order NOT placed: ${outcome.why}.`);
      addDirectNote({ recId, kind: 'not-removed', label, brokerLabel, orderId: null });
    }
    return;
  }
  if (outcome.verdict === 'keep') {
    keepRow(outcome.why, outcome.orderId);
    return;
  }

  const orderId = outcome.orderId;
  try {
    applyPersistedPosition(
      saved,
      { ...pos, contracts: orderQty, sourceLabel: `${brokerLabel} — ${orderType === 'LMT' ? 'Limit' : 'Market'} (ID: ${orderId})` },
      addPosition,
      (q) => addSaveNote(`${label}: ${sizeNote(q)}`),
      (r, why, kept) => addSaveNote(`${label}: ${droppedStopNote(r, why, kept)}`),
    );
  } catch (e) {
    setOrderError(`${label}: Order placed (ID ${orderId}) but the local view failed to update: ${String(e)}`);
  }
  setPaperOrderId({ label, id: orderId });
} catch (e) {
  // Unreachable by design (every call above is guarded); if it is ever
  // reached, the order's fate is unknown and the row stays with a note.
  keepRow(String(e), null);
}

export function SendToBrokerDialog({ cards, quoteWarningsByContract, contractsBySymbol, overridesBySymbol, invalidationBySymbol, methodPickBySymbol, onClose, onSubmit }: Props) {
  const [rows, setRows] = useState<Record<string, RowState>>(() =>
    Object.fromEntries(cards.map((c) => [c.symbol, { contracts: contractsBySymbol[c.symbol] ?? 1 }])),
  );
  const [overrideReady, setOverrideReady] = useState(false);

  const limits = useRiskStore((s) => s.limits);
  const dailyRecommendations = useRiskStore((s) => s.dailyRecommendations);
  const positions = usePortfolioStore((s) => s.positions);

  const estTotal = useMemo(() => {
    let t = 0;
    for (const c of cards) {
      const r = rows[c.symbol] ?? { contracts: 1 };
      const mid = c.contractDetails?.mid ?? 0;
      t += mid * 100 * r.contracts;
    }
    return t;
  }, [cards, rows]);

  const riskChecks = useMemo(() => {
    const checks: Record<string, RiskCheckResult> = {};
    for (const c of cards) {
      const r = rows[c.symbol] ?? { contracts: 1 };
      checks[c.symbol] = checkTradeRisk(
        c, Math.max(1, Math.round(r.contracts)), limits, positions, dailyRecommendations,
        overridesBySymbol[c.symbol] ?? null,
        invalidationBySymbol[c.symbol] ?? c.exit.invalidation,
        methodPickBySymbol[c.symbol] ?? null,
      );
    }
    return checks;
  }, [cards, rows, limits, positions, dailyRecommendations, overridesBySymbol, invalidationBySymbol, methodPickBySymbol]);

  const hasMissingInvalidation = useMemo(
    () => Object.values(riskChecks).some((rc) => rc.reasons.includes('missing_invalidation')),
    [riskChecks],
  );

  const hasMissingMethodPick = useMemo(
    () => Object.values(riskChecks).some((rc) => rc.reasons.includes('missing_method_pick')),
    [riskChecks],
  );

  const hasWarnings = useMemo(
    () => Object.values(riskChecks).some((rc) =>
      !rc.approved
      && !rc.reasons.includes('missing_invalidation')
      && !rc.reasons.includes('missing_method_pick'),
    ),
    [riskChecks],
  );

  const allClean = useMemo(
    () => Object.values(riskChecks).every((rc) => rc.approved),
    [riskChecks],
  );

  const patch = (sym: string, p: Partial<RowState>) => {
    setOverrideReady(false);
    setRows((r) => ({ ...r, [sym]: { ...(r[sym] ?? { contracts: 1 }), ...p } }));
  };

  const submit = () => {
    if (hasMissingInvalidation) return;
    if (hasMissingMethodPick) return;
    if (hasWarnings && !overrideReady) {
      setOverrideReady(true);
      return;
    }
    const orders: DraftOrder[] = cards.map((c) => {
      const r = rows[c.symbol] ?? { contracts: 1 };
      return { card: c, contracts: Math.max(1, Math.round(r.contracts)) };
    });
    onSubmit(orders, overrideReady);
  };

  return (
    <div className={styles.backdrop} onClick={onClose} role="presentation">
      <div
        className={styles.dialog}
        onClick={(e) => e.stopPropagation()}
        role="dialog"
        aria-modal="true"
        aria-label="Track basket in Portfolio"
      >

export function normaliseStatus(status: unknown): string {
  // Defensive: an Enum repr must never slip past as unknown-and-safe.
  return String(status ?? '').trim().toLowerCase().replace(/^orderstatus\./, '');
}

const ACCEPTED_NOT_FILLED = new Set([
  'accepted', 'presubmitted', 'submitted', 'pending', 'pendingsubmit', 'pendingnew', 'new',
]);

/** Accepted, pending, and submitted broker statuses are not fills. */
export function isAcceptedNotFilled(status: unknown): boolean {
  const token = normaliseStatus(status).replace(/[\s_]/g, '');
  return ACCEPTED_NOT_FILLED.has(token);
}

export type DirectOutcome =
  | { verdict: 'placed'; orderId: string }
  | { verdict: 'delete'; why: string }
  | { verdict: 'keep'; why: string; orderId: string | null };

/** Classify a direct send's broker outcome: a thrown error, or a 2xx body. */
export function classifyDirectFailure(
  input: { thrown: unknown } | { response: unknown },
): DirectOutcome {
  if ('thrown' in input) {
    const { status, detail } = parseApiError(input.thrown);
    const why = whyOf(input.thrown);
    const d = detail ?? '';
    const preSubmit =
      status === 422
      || (status === 503 && d.startsWith('Broker credentials unavailable'))
      || (status === 400 && (d.startsWith('live trading via') || d.startsWith('Unknown broker')))
      // A PREFIX match: other adapters echo broker text into their 502s.
      || (status === 502 && d.startsWith('IBKR did not place the order:'));
    return preSubmit ? { verdict: 'delete', why } : { verdict: 'keep', why, orderId: null };
  }
  const res = (input.response ?? {}) as { order_id?: unknown; status?: unknown };
  const rawStatus = String(res.status ?? '');
  const status = normaliseStatus(res.status);
  const id = typeof res.order_id === 'string' ? res.order_id.trim() : '';
  const usableId = id !== '' && id.toLowerCase() !== 'unknown' ? id : null;
  if (status === 'rejected') return { verdict: 'delete', why: `broker status ${rawStatus}` };
  if (TERMINAL_KEEP.has(status)) return { verdict: 'keep', why: `broker status ${rawStatus}`, orderId: usableId };
  if (usableId == null) {
    return { verdict: 'keep', why: `broker reply had no usable order ID${rawStatus ? ` (status ${rawStatus})` : ''}`, orderId: null };

