/*
 * StatusBadge — PASS / CAUTION / REJECT / PENDING / NO DATA.
 * Drift log Screen 1 #5 (correct labels), Screen 3 #6 (confidence badges).
 */

import type { Status } from '@/lib/status';
import { STATUS_LABEL } from '@/lib/status';
import { Tooltip } from '@/components/atoms/Tooltip';
import styles from './StatusBadge.module.css';

interface StatusBadgeProps {
  status: Status;
  /** Optional override of the default label (e.g. 'HIGH CONFIDENCE'). */
  label?: string;
  className?: string;
  /** Business-interpretation tooltip shown on hover. */
  tooltip?: string;
  tooltipPosition?: 'top' | 'bottom';
  tooltipAlign?: 'center' | 'right';
}

const STATUS_CLASS: Record<Status, string> = {
  PASS:    styles.pass,
  CAUTION: styles.caution,
  REJECT:  styles.reject,
  PENDING: styles.pending,
  NO_DATA: styles.noData,
};

export function StatusBadge({ status, label, className, tooltip, tooltipPosition, tooltipAlign }: StatusBadgeProps) {
  const badge = (
    <span className={[styles.badge, STATUS_CLASS[status], className].filter(Boolean).join(' ')}>
      {label ?? STATUS_LABEL[status]}
    </span>
  );
  if (tooltip) {
    return (
      <Tooltip text={tooltip} position={tooltipPosition} align={tooltipAlign}>
        {badge}
      </Tooltip>
    );
  }
  return badge;
}

/*
 * StatusBadge — spec §5 STATUS BADGE.
 * Pill, 4px radius, DM Sans 11px SemiBold uppercase, 2px 8px padding, 1px border.
 */

.badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 2px 8px;
  border-radius: var(--radius-sm);
  border: 1px solid transparent;
  font-family: var(--font-dm), system-ui, sans-serif;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  line-height: 1.4;
  white-space: nowrap;
}

.pass {
  background: var(--pass-bg);
  color: var(--pass);
  border-color: var(--pass-border);
}

.caution {
  background: var(--caution-bg);
  color: var(--caution);
  border-color: var(--caution-border);
}

.reject {
  background: var(--reject-bg);
  color: var(--reject);
  border-color: var(--reject-border);
}

.pending {
  background: var(--neutral-bg);
  color: var(--neutral);
  border-color: var(--neutral);
}

.noData {
  background: var(--neutral-bg);
  color: var(--text-dim);
  border-color: var(--border-subtle);
}

export function triggerDetailText(d?: TriggerDetail): string | undefined {
  if (!d) return undefined;
  const checks = [
    d.macd_pass  ? 'MACD ✓'  : 'MACD ✗',
    d.rsi_pass   ? 'RSI ✓'   : 'RSI ✗',
    d.stoch_pass ? 'Stoch ✓' : 'Stoch ✗',
  ].join(' · ');
  const candle = d.candle !== 'none' ? d.candle : '';
  const vol = d.volume_bonus ? ' + vol' : '';
  return [candle, `${checks} · ${d.momentum_count}/3 signals${vol}`].filter(Boolean).join(' · ') || undefined;
}

export function pullbackDetailText(d?: PullbackDetail): string | undefined {
  if (!d) return undefined;
  const ret = d.retracement_pct != null ? `Ret ${d.retracement_pct.toFixed(1)}%` : '';
  const fvg = d.fvg_hit ? '+ FVG' : '';
  // d.reason is typed as required, but the un-validated /api/analyze-stock path can
  // forward a raw dict missing it (e.g. the atr_fallback branch of _rule_pullback) —
  // `|| undefined` (not just relying on filter(Boolean)) ensures an all-empty result
  // falls back to the caller's generic status copy instead of silently rendering no
  // tooltip at all.
  return [ret, fvg, d.reason].filter(Boolean).join(' · ') || undefined;
}

export function trendDetailText(d?: TrendDetail): string | undefined {
