const TIER_TOOLTIP: Record<ConfidenceTier, string> = {
  high:    'High signal confidence — in backtests this pattern consistently beat a 50/50 baseline by a wide margin. Trade at normal size.',
  moderate:'Moderate signal confidence — the pattern shows a positive backtest edge, but not a dominant one. Normal caution applies.',
  low:     'Low signal confidence — this pattern has historically underperformed a 50/50 baseline in backtests. The signal may still be valid, but there is less statistical backing. Consider smaller size or skipping.',
  unknown: 'Fewer than 20 non-overlapping past setups. Not enough history to validate this pattern, so it cannot reach PASS.',
};

export function ConfidenceBadge({
  confidence,
  title,
}: {
  confidence: number | null | undefined;
  title?: string;
}) {
  const tier = confidenceTier(confidence);
  const tone = confidenceTone(tier);
  const label = confidence === null || confidence === undefined ? 'Unvalidated' : `${confidence}%`;
  const tooltipText = title ?? TIER_TOOLTIP[tier];
  return (
    <Tooltip text={tooltipText}>
      <span className={styles.badge} data-tier={tier}>
        <Data size={12} weight={500} tone={tone}>
          {label}
        </Data>
      </span>
    </Tooltip>
  );
}

import type { DataTone } from '@/components/primitives';

// Mirrors backend/config/scoring_rules.yaml's confidence_gate
// (cautionBelow: 50, rejectBelow: 35), consumed by status_cap() in
// backend/app/scoring/signal_confidence.py.
export type ConfidenceTier = 'unknown' | 'low' | 'moderate' | 'high';

export function confidenceTier(confidence: number | null | undefined): ConfidenceTier {
  if (confidence === null || confidence === undefined) return 'unknown';
  if (confidence >= 50) return 'high';
  if (confidence >= 35) return 'moderate';
  return 'low';
}

export function confidenceTone(tier: ConfidenceTier): DataTone {
  switch (tier) {
    case 'high':     return 'pass';
    case 'moderate': return 'caution';
    case 'low':      return 'reject';
    // 'unknown' = Unvalidated: fewer than 20 non-overlapping setups. The
    // backend caps such a card at CAUTION, so it reads in the caution tone.
    default:         return 'caution';
  }
}

/** Age is trailing input bars. The average is transition strides, not days. */

export function formatRegimeAge(ageBars: number): string {
  return `${ageBars} bars`;
}

export function formatRegimeAverage(avgStrides: number, strideBars?: number | null): string {
  if (!Number.isFinite(avgStrides)) return '';
  const shown = avgStrides.toFixed(1).replace(/\.0$/, '');
  const sized = typeof strideBars === 'number' && Number.isInteger(strideBars) && strideBars >= 1;
  return sized ? `≈${shown} strides of ${strideBars} bars` : `≈${shown} strides`;
}

export function stopPremiumRisk(c: StopCostOut | null): StopPremiumRisk | null {
  if (!c) return null;
  const nums = [c.lossDollar, c.valueAtStop, c.fraction, c.passMaxFraction, c.premium, c.stopPrice];
  if (!nums.every(Number.isFinite)) return null;
  if (c.premium < 0.01) return null;
  return {
    premium:         c.premium,
    valueAtStop:     c.valueAtStop,
    loss:            c.lossDollar,
    stopPrice:       c.stopPrice,
    fraction:        c.fraction,
    passMaxFraction: c.passMaxFraction,
    status:          c.status,
    basis:           c.basis,
  };
}

/** The two figures every readout below scales from, in whole cents.
 *
 *  The server hands these over already quantized, so this is a unit change and
 *  not a rounding step — but it stays the single place the conversion happens,
 *  because the defect this file spent five audit rounds removing was two
 *  precisions deciding one printed line. Comparing and subtracting in integer
 *  cents also keeps `$0.16 of $0.20` from turning into 0.7999999999999999 the
 *  moment anything divides the two dollar doubles. */
function cents(r: StopPremiumRisk) {
  return { loss: Math.round(r.loss * 100), premium: Math.round(r.premium * 100) };
}

/** The gate's inputs on one line, so the verdict is auditable at a glance:
 *  "$5.20 premium − $1.49 at $185.87 = $3.71 of $5.20 premium".
 *
 *  A formatter rather than inline JSX because interpolating this many values
 *  into markup splits it across text nodes — unreadable in the DOM and
 *  untestable by `getByText`. Same reasoning as

export function formatStopPremiumRisk(r: StopPremiumRisk): string {
  return (
    `$${r.premium.toFixed(2)} premium − $${r.valueAtStop.toFixed(2)} ` +
    `at $${r.stopPrice.toFixed(2)} = ` +
    `$${r.loss.toFixed(2)} of $${r.premium.toFixed(2)} premium` +
    ` · Black-Scholes, priced today`
  );
}

/** Whether the stop is a TOTAL LOSS on the figures actually printed.
 *
 *  Exported so the badge's tooltip branches on the same figures as the words
 *  around it. It used to be possible for the tooltip to call a contract a
 *  total loss while the money beside it read "$1 left", because the two came
 *  from different precisions; both now come from `cents`. */
export function stopLossIsTotalOnPrintedFigures(r: StopPremiumRisk): boolean {
  const c = cents(r);
  return c.loss >= c.premium;
}

/** The badge label: the verdict, the percentage, AND what survives the stop,
 *  per share.
 *
 *  Decision BADGE-SPEC-2026-09-05 (Kenneth). The schematic's card 03 puts the
 *  dollars-left on the badge itself and per SHARE — "Caution · 71% of premium
 *  · $1.49 left". The reason it matters beyond this card: the badge is what
 *  the ranking view will reuse, and there it would travel with only a
 *  percentage, which is the half that does not tell you whether being wrong
 *  costs $8 or $800.
 *
 *  UNITS ARE NAMED ON BOTH LINES, deliberately. This card shows the same
 *  quantity twice a foot apart in two units — $1.49 per share here, $149 per
 *  contract on the headline. That is the schematic's layout, not an accident,
 *  so each string says which it is rather than leaving a reader to conclude
 *  the card contradicts itself by a factor of a hundred. "/share" rather than
 *  "a share" because StatusBadge uppercases its label and is
 *  `white-space: nowrap` — "$1.49/SHARE LEFT" sits in the space the badge has,
 *  "$1.49 A SHARE LEFT" does not.
 *
 *  THE VERDICT WORD LEADS, as the schematic has it. StatusBadge renders
 *  `label ?? STATUS_LABEL[status]`, so supplying a label REPLACES the word —
 *  and dropping it left colour as the only thing separating two badges that
 *  print the same percentage. The percentage is rounded to a whole point and
 *  the verdict is not, so a badge carrying only the percentage is genuinely
 *  ambiguous near the line; the word is what settles it. */
export function formatStopLossBadge(r: StopPremiumRisk): string {
  const c = cents(r);
  const left = c.premium - c.loss;
  return `${STATUS_LABEL[r.status]} · ${formatStopLossPct(r)} of premium · $${(left / 100).toFixed(2)}/share left`;
}

/** The badge's percentage.
 *
 *  Taken from `fraction`, which is the number the SERVER decided the verdict
 *  on, so the percentage and the colour beside it can never be read off two
 *  different quantities — the failure mode that put "100% OF PREMIUM" next to
 *  "of the $1,890 premium, $8 left" on this card before.
 *
 *  100% is reserved for an actual total loss on the printed cents. `fraction`
 *  is rounded to hundredths server-side, so a contract with one cent of a
 *  $5.20 premium left rounds to 1.00 and would otherwise assert a total loss
 *  the money beside it contradicts; anything with a cent left reads at most
 *  99%.
 *
 *  0% is NOT reserved in the same way, and the asymmetry is deliberate. The
 *  two ends are different kinds of claim: "100% of premium" beside "$1.49/share
 *  left" is IMPOSSIBLE, while "0% of premium" beside "$9.99/share left" is
 *  merely a percentage rounded to the nearest whole point, which is what every
 *  other figure on the badge is too. Forcing the bottom up to 1% would break
 *  the stronger property — that the printed percentage is within half a point
 *  of the true fraction. */
export function formatStopLossPct(r: StopPremiumRisk): string {
  const c = cents(r);
  if (c.premium <= 0) return '0%';
  if (c.loss >= c.premium) return '100%';
  return `${Math.min(99, Math.max(0, Math.round(r.fraction * 100)))}%`;
}

/** The headline the badge's percentage is a summary OF: what one contract
 *  actually loses at the stop, and what is left afterwards.
 *
 *  Dollars per CONTRACT, not per share, because that is the number being
 *  risked — the arithmetic line below it stays per-share so it reconciles with
 *  the premium printed there. `$824 of the $1,890 premium, $1,066 left`.
 *
 *  "of the $1,890 PREMIUM", never "you paid". Two figures on this very card
 *  disagree with "paid": the order strip's Limit is freely editable, and CaR
 *  three rows up is `mid × contracts × 100`, so at Contracts=3 it reads $5,670
 *  against this line's $1,890. Both halves of this sentence are per contract
 *  and at the premium the gate priced; saying so is the difference between a
 *  figure that reconciles with CaR by division and one that looks like a
 *  contradiction.
 *
 *  `left` is subtracted from the already-rounded pair rather than rounded on
 *  its own, so the three figures cannot fail to add up. Rounding all three
 *  independently is how this line once read "$401 per contract — of the $651
 *  you paid, $251 left". */
export function formatStopLossHeadline(r: StopPremiumRisk): string {
  const c = cents(r);
  const left = c.premium - c.loss;
  const usd = (n: number) => `$${n.toLocaleString('en-US')}`;
  return `${usd(c.loss)} per contract — of the ${usd(c.premium)} premium, ${usd(left)} left`;
}

export function maxLossAtStop(
  entryPremium: number,
  stopContractPrice: number,
  contracts: number,
): number {
  return Math.max(0, entryPremium - stopContractPrice) * contracts * 100;
}

/** Resolves the $ threshold `maxLossAtStop` is checked against — a per-trade
 *  override (fixed dollar or percent of portfolioValue) if one is set,
 *  otherwise the global `maxLossPerTradePct` default. */
export function resolveMaxLossLimitDollar(
  portfolioValue: number,
  globalPct: number,
  override?: MaxLossOverride | null,
): number {
  if (override) {
    return override.mode === 'dollar' ? override.value : portfolioValue * override.value;
  }
  return portfolioValue * globalPct;
}

/** Risk-derived contract size: how many whole contracts the given risk
 *  budget affords at the given per-contract risk (typically the exit-plan
 *  pipeline's `maxLossAtStop(entryPremium, stop.contractPrice, 1)`), rounded
 *  down. Returns both the floored recommendation and the raw decimal so the
 *  UI can show "3 contracts (3.71 exact)" rather than just the rounded
 *  number. Returns null when there's no meaningful answer — a non-positive
 *  budget, or a non-positive per-contract risk (the stop reprices at or
 *  above entry premium, i.e. not actually a loss on this leg).
 *
 *  `recommended` floors `raw + FLOOR_EPSILON` rather than `raw` directly —
 *  `riskPerContract` is a subtraction of two dollar floats (entry premium
 *  minus a repriced stop price, see `maxLossAtStop`), which routinely lands
 *  a few ULPs off the exact cent value (e.g. 1.00 - 0.41 === 0.5900000000000001
 *  in IEEE754). At an exact-multiple budget that noise pushes `raw` to
 *  0.9999999999999999 instead of 1.0, silently under-recommending by a
 *  whole contract. The epsilon is far too small to change any real,
 *  intentionally-fractional recommendation. */
const FLOOR_EPSILON = 1e-9;

export interface RecommendedContractSize {
  raw: number;
  recommended: number;
}

export function recommendedContractSize(
  riskBudget: number,
  riskPerContract: number,
): RecommendedContractSize | null {
  if (riskBudget <= 0 || riskPerContract <= 0) return null;
  const raw = riskBudget / riskPerContract;
  return { raw, recommended: Math.floor(raw + FLOOR_EPSILON) };
}

/** Formats a `recommendedContractSize` result for display as "N.dd" — always
 *  showing `size.recommended` as the whole part, by construction. Two
 *  earlier versions independently re-derived a floored/truncated decimal
 *  from `raw` (once via bare `toFixed`, once via a second, separately-
 *  epsilon-adjusted floor) — each fixed a real IEEE754 boundary disagreement
 *  with `recommended`, and each was later shown to have its own, narrower
 *  boundary where the two could still disagree, since two independent
 *  floating-point computations over the same input can be tuned to agree at
 *  every practically-reachable boundary but never proven to agree at every
 *  boundary. Deriving the decimal from `size.recommended` (already the
 *  authoritative, epsilon-corrected integer) instead of re-flooring `raw`
 *  a third time eliminates that whole bug class rather than patching the
 *  next boundary: the whole part can never disagree with `recommended`
 *  because it never comes from anywhere else. `Math.max(0, ...)` guards the
 *  fractional remainder against the same sub-epsilon negative noise
 *  `FLOOR_EPSILON` exists to absorb (e.g. raw fractionally *below*
 *  `recommended` by a few ULPs). */
export function formatRecommendedContractSizeRaw(size: RecommendedContractSize): string {
  const fractionCents = Math.min(99, Math.floor(Math.max(0, size.raw - size.recommended) * 100));
  return `${size.recommended}.${String(fractionCents).padStart(2, '0')}`;

export function checkTradeRisk(
  card: TradeCardData,
  proposedContracts: number,
  limits: RiskLimits,
  positions: PortfolioPosition[],
  dailyRecommendations: number,
  /** Feature 5 (Arithmetic Profit Target card) — the active PRE-trade
   *  max-loss override for this symbol, if the user has set one via the
   *  Arithmetic card. `undefined`/`null` inherits the global
   *  `maxLossPerTradePct` default, same as no override at all. */
  maxLossOverride?: MaxLossOverride | null,
  /** PIECE 3. The stop the card is actually SHOWING, when the caller has
   *  resolved one — step 7's `invalidationFor`, i.e. the user's typed value
   *  when the Invalidation field is touched, else the card's own.
   *
   *  It matters only now that `card.exit.invalidation` can be null. Before
   *  piece 3 the scan always sent a number and `missing_invalidation` was
   *  effectively unreachable; the v15 migration makes it live, and reading the
   *  CARD alone would then refuse to send a restored candidate even after the
   *  user typed a stop into it — the one gesture that fixes the card. Pass
   *  `undefined` to fall back to the card, which is what every caller with no
   *  overlay to consult should do. */
  resolvedInvalidation?: number | null,
  /** Phase G piece 5, build step 4 (§7.1) — the trader's explicit method
   *  pick for this card, resolved by the caller exactly as `resolvedInvalidation`
   *  is: step 7's `methodPickFor`, keyed by contract through `editKeyFor`.
   *  `undefined`/`null` alike mean no pick, since `MethodPick` has no
   *  card-level fallback the way invalidation falls back to `card.exit.*` —
   *  a pick is a decision a human made, not a field the card seeds. */
  methodPick?: MethodPick | null,
): RiskCheckResult {
  const reasons: string[] = [];
  let approved = true;

  const mid = card.contractDetails?.mid ?? 0;
  const car = capitalAtRisk(mid, proposedContracts);
  const singleExposure = exposurePct(car, limits.portfolioValue);
  // Options only (this check runs on the options basket): stock rows count
  // against the stock total, not this one (STOCK-SENDS).
  const currentNotional = totalNotional(positions, 'option');
  const totalExposure = exposurePct(currentNotional + car, limits.portfolioValue);

  if (!checkInvalidation(resolvedInvalidation ?? card.exit.invalidation)) {
    reasons.push('missing_invalidation');
    approved = false;
  }

  if (!checkMethodPick(methodPick)) {
    reasons.push('missing_method_pick');
    approved = false;
  }

  // Review fix #4 (decision D5): this check runs on the options basket only,
  // and an option order carries no protective order, so its worst-case loss is
  // the whole premium. `maxLossPerTradePct` therefore caps premium as well, and
  // the effective cap is the smaller of the two. Both limits and
  // `singleExposure` are fractions of portfolio value (0.05 = 5%). Mirrors
  // backend `portfolio_risk.check_position_risk`; stocks never reach here.
  const maxSingleOption = Math.min(limits.maxSingleTradeExposurePct, limits.maxLossPerTradePct);
  if (singleExposure > maxSingleOption) {
    reasons.push('single_trade_exposure_too_high');
    approved = false;
  }

  if (totalExposure > limits.maxTotalExposurePct) {
    reasons.push('total_exposure_limit_reached');
    approved = false;
  }

  if (positions.length >= limits.maxConcurrentPositions) {
    reasons.push('max_concurrent_positions_reached');
    approved = false;
  }

  if (positions.some((p) => p.symbol === card.symbol)) {
    reasons.push('duplicate_symbol');
    approved = false;
  }

  if (dailyRecommendations >= limits.maxDailyRecommendations) {
    reasons.push('max_daily_recommendations_reached');
    approved = false;
  }

  // Feature 5 — a per-trade PRE-trade override now can exist (set on the
  // Arithmetic card, passed in via `maxLossOverride` above), resolved through
  // the same shared `resolveMaxLossLimitDollar` the post-trade override
  // (PortfolioPosition.maxLossOverride, via the Portfolio EditDrawer) already
  // uses — one resolution function, not two subtly different ones. Absent an
  // override, this still falls back to the global default. Skipped entirely
  // when no exit plan has been computed yet (nothing to reprice against).
  let lossAtStop: number | undefined;
  let lossLimitDollar: number | undefined;
  const exitPlan = card.exit.exitPlan;
  if (exitPlan) {
    // `cd.mid` is the scan-time snapshot, while `exitPlan.stop.contractPrice`
    // came from a fresh quote fetched when "Compute Exit Plan" ran (see the
    // comment on TradeCard's computeExitPlan) — the two don't share a
    // baseline if premium moved between scan and click. Same limitation as
    // `capitalAtRisk(mid, ...)` above, which this mirrors deliberately
    // rather than inventing a second, inconsistent convention; `ExitPlan`
    // doesn't currently carry the fresh premium it was computed against, so
    // fixing this for real means threading that value through as a new
    // field, which is out of scope here.
    const entryPremium = card.contractDetails?.mid ?? 0;
    lossAtStop = maxLossAtStop(entryPremium, exitPlan.stop.contractPrice, proposedContracts);
    lossLimitDollar = resolveMaxLossLimitDollar(limits.portfolioValue, limits.maxLossPerTradePct, maxLossOverride);
    if (lossAtStop > lossLimitDollar) {
      reasons.push('max_loss_per_trade_exceeded');
      approved = false;
    }
  }

  return {
    approved,
    reasons,
    singleExposurePct: singleExposure,
    totalExposurePct: totalExposure,
    capitalAtRisk: car,
    maxLossAtStop: lossAtStop,
    maxLossLimitDollar: lossLimitDollar,
  };
}

 *  too — it reads a stored/derived fraction rather than accepting a typed one.
 *
 *  Fractions, matching `premiumStopPct` itself — multiply by 100 for the
 *  percent an editor shows. */
export const PREMIUM_STOP_MIN_PCT = 0.10;
export const PREMIUM_STOP_MAX_PCT = 0.99;

/** The DOLLAR bounds for a per-position premium stop quoted against `mid`.
 *
 *  TradeCard edits the stop in dollars and the drawer edits it as a percent,
 *  so the card has to convert — and it did that with `Math.round(n * 100) / 100`
 *  on both ends, which shaves up to half a cent in EITHER direction. That put
 *  the card's own boundary values OUTSIDE the band the drawer enforces: a
 *  $5.24 mid gave a minimum of $0.52 = 9.92%, and a $1.01 mid gave a maximum
 *  of $1.00 = 99.01%. A stop created at the card's own minimum was then one
 *  the drawer refused — the exact disagreement the shared band exists to end,
 *  surviving at the boundary for most mids.
 *
 *  So the rounding goes OUTWARD-TO-INWARD: ceil the floor, floor the ceiling.
 *  Both ends land inside the band at 2dp, which is the precision the card's
 *  editor commits at.
 *
 *  IN INTEGER CENTS, and that is not tidiness. `Math.ceil(mid * 0.10 * 100)`
 *  is evaluated in binary floats, and on exactly the mids where 10% IS
 *  expressible at 2dp -- every multiple of a dime -- the product lands a few
 *  ulps above the integer and `ceil` climbs a whole cent: a $3.00 mid gave
 *  $0.31 (10.33%) where $0.30 is exactly 10% and the drawer accepts it. Round
 *  2 of the follow-up audit measured 172 such mids between $0.02 and $50, and
 *  they are precisely the round numbers a user is most likely to be looking
 *  at. A card refusing a stop the drawer accepts is the disagreement this
 *  helper exists to end, so it cannot be reintroduced by the arithmetic that
 *  ends it.
 *
 *  `Math.max(0.01, ...)` on the floor covers a SUB-PENNY mid, where the cent
 *  count is 0 and the ceiling of nothing is nothing; `Math.max(min, ...)` on
 *  the ceiling covers the degenerate top of that range, where 2dp cannot
 *  express the band at all -- at a $0.01 mid the floor and the ceiling
 *  collapse onto the same penny. That single value is 100% of the mid, which
 *  the backend refuses to store (`0 < ratio < 1`) and which
 *  `barrierRace.premiumStopPctFromDollars` returns undefined for, so at a
 *  $0.01 mid the field offers exactly one dollar and that dollar produces no
 *  stop. TradeCard therefore renders the row READ-ONLY there (P2-24): the
 *  global applies, or a stop the user already typed is kept and shown as
 *  pinned (decision Q-P2-2). See round_2_batch_followups R2-6. */
export function premiumStopDollarBounds(mid: number): { min: number; max: number } {
  const cents = Math.round(mid * 100);
  const minCents = Math.max(1, Math.ceil(cents * PREMIUM_STOP_MIN_PCT));
  const min = minCents / 100;
  // STOP-SEMANTICS (b): the ceiling is the largest whole-cent stop that is NOT
  // sub-cent at this mid, found by stepping down in integer cents from the 99%
  // cap. `floor(cents * 0.99)` alone offered stops that can never fire -- 43
  // mids from $0.02 to $50 (a $0.03 mid offered $0.02, whose threshold is a few
  // ulps under a cent). One step is always enough there; the loop is bounded
  // by `minCents` anyway. When nothing qualifies (a $0.01 mid) the old
  // degenerate `max = min` stands, so TradeCard's read-only detection is
  // unchanged.
  let maxCents = Math.floor(cents * PREMIUM_STOP_MAX_PCT);
  while (maxCents >= minCents && premiumStopIsSubCent(mid, maxCents / 100 / mid, false)) {
    maxCents -= 1;
  }
  const max = Math.max(min, maxCents / 100);
  return { min, max };

}

/** Exported for tests only (P2-20). */
export function EditableKV({
  label,
  value,
  onChange,
  onRevert,
  min,
  max,
  mono,
  tone,
  prefix = '',
  suffix = '',
  decimals = 2,
  nullLabel = 'not computed',
}: {
  label: string;
  /** NULL renders `nullLabel` and starts the editor with an EMPTY draft, so a
   *  field whose plan value is "not computed" can still be typed into. Only
   *  the Invalidation field passes null today — see
   *  `TradeCardData.exit.invalidation`. */
  value: number | null;
  onChange: (v: number) => void;
  /** Optional "clear the field to go back to inheriting the plan's value".
   *  Only the three threaded fields pass it; for every other field an empty
   *  input still means "I changed my mind", i.e. nothing happens. */
  onRevert?: () => void;
  min?: number;
  max?: number;
  mono?: boolean;
  tone?: 'pass' | 'caution' | 'reject';
  prefix?: string;
  suffix?: string;
  decimals?: number;
  /** What to show in place of a number when `value` is null. Required in
   *  practice for any field that can be null: the default is deliberately
   *  wordy rather than a bare dash, because a dash beside an editable field
   *  reads as zero. */
  nullLabel?: string;
}) {
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState(value == null ? '' : String(value));
  // ROUND 9 finding 17 -- the out-of-range REJECT used to be entirely silent:
  // `setEditing(false)` and the field showed the old number again, so a user
  // who typed 1400 and looked away could not tell a refusal from an
  // acceptance, and nothing hinted that a legitimately wider value was
  // available inside the range. A safety gate nobody can perceive teaches
  // nothing. Announced politely (aria-live) rather than as an alert: the value
  // on screen is correct throughout, it is the typed one that was dropped.
  const [rejected, setRejected] = useState<string | null>(null);

  /** CODE ROUND 1, C1-2 -- did the user TYPE since the editor opened? The
   *  value-comparison guards in `save` compare the draft (seeded once, at
   *  `startEdit`) with the CURRENT `value` prop, so a value that moves while
   *  the field is open -- TradeCard's untouched premium stop switching from
   *  the scan seed to `round(liveMid x global, 2)` when the live quote lands
   *  -- made a bare focus-and-blur commit the stale seed as a deliberate,
   *  touched stop. Nothing typed is nothing committed, whatever `value` did. */
  const typedRef = useRef(false);

  const startEdit = useCallback(() => {
    setDraft(value == null ? '' : String(value));
    setRejected(null);
    typedRef.current = false;
    setEditing(true);
  }, [value]);

  const save = useCallback(() => {
    if (!typedRef.current) {
      setEditing(false);
      return;
    }
    // A COMPLETE decimal literal, or nothing. `parseFloat` is happy to
    // TRUNCATE: it reads "2." as 2 and "2.7abc" as 2.7, and nothing downstream
    // can tell a finished number from an interrupted one.
    //
    // Round 8 moved this input to type="text" so a half-typed "2." would stop
    // being sanitized to "" and misread as the clear-to-inherit gesture. That
    // was right, and it left the other half open: the string now survives all
    // the way to `parseFloat`, which quietly commits 2. A user with a
    // committed $2.71 who reopened the field to type $2.40, got as far as "2."
    // and tabbed away, ended up with $2.00 shown, `touched` set, and
    // `limit_price: 2.00` on a live BUY/OPEN order -- round 8 traded "reverts
    // to a value the user didn't choose" for "commits a value the user didn't
    // choose", and only the second one reaches a broker.
    //
    // A trailing point is the interrupted case; ".5" is a complete way to
    // write 0.5 and stays accepted. Anything incomplete is a no-op, showing
    // the previous value back -- the same honest answer the out-of-range
    // policy below gives.
    const trimmed = draft.trim();
    const isCompleteNumber = /^-?(?:\d+(?:\.\d+)?|\.\d+)$/.test(trimmed);
    if (trimmed !== '' && !isCompleteNumber) {
      // ROUND 10 finding 9 -- SAY SO HERE TOO. Round 9 added this guard four
      // lines above the fix for "the reject gave no feedback whatsoever", and
      // gave it exactly that property: a user who typed "2." and tabbed away
      // saw the old value return with nothing to explain it. Same defect, same
      // commit, different branch.
      setRejected(`That is not a complete number — kept the previous value.`);
      setEditing(false);
      return;
    }
    const parsed = parseFloat(draft);
    if (isNaN(parsed)) {
      // An EMPTY field is a deliberate gesture, not a typo: on a field that can
      // inherit, it means "stop pinning this, follow the plan again". Anything
      // else unparseable ("abc", "1.2.3") keeps the old no-op behaviour.
      if (onRevert && draft.trim() === '') onRevert();
      setEditing(false);
      return;
    }
    const minVal = min ?? -Infinity;
    const maxVal = max ?? Infinity;
    // OUT OF RANGE REVERTS, IT DOES NOT CLAMP.
    //
    // Round 8: clamping turns a fat-finger into a plausible-looking WRONG
    // number rather than rejecting it. On a $150 bullish card, "1400" typed for
    // "140" clamped to $148.50 -- 1% below spot -- which `buildPaperPosition`
    // stores as `PortfolioPosition.stop` and `alertEngine` fires STOP_REACHED
    // on at the first ordinary intraday wiggle, Gmail and Telegram behind it,
    // while the user believes their stop is 7% away. The mirror case "14"
    // clamped to $75.00, a 50% stop, equally silently.
    //
    // The portfolio EditDrawer's premium-stop editor already took this
    // position on the identical question ("Out of range REVERTS, it does not
    // clear ... showing the previous value back is the honest answer"). Two
    // editors in one branch with opposite policies, and the card had the unsafe
    // one on the field that becomes the position's stop.
    //
    // Reverting retired round 6's seed-outside-bounds WRITE at the source: the
    // clamp was what made `next !== value` on a bare focus-and-blur when the
    // SEED itself sat outside [min,max]. With no clamp there is nothing to
    // differ, so nothing is written.
    //
    // It did not retire the MESSAGE, and round 2 of the follow-up audit found
    // that half still live: this check sat ABOVE the no-op guard, so a seed
    // outside the bounds printed "Must be between $X and $Y — kept the
    // previous value." for a value the user never typed, merely for clicking
    // the field to read it. The no-op guard is therefore hoisted above this
    // one. Nothing typed is nothing judged -- the same rule PremiumStopEditor's
    // `if (!dirtyRef.current)` guard applies in the drawer.
    //
    // Reachable, and this branch widened it: `premiumStopDollarBounds` rounds
    // the minimum UP (it must, or the card's own boundary falls below the band
    // the drawer enforces) while the seed is `round(mid x global, 2)`
    // (trade_plan.py). At a global of 0.10 -- the minimum Settings offers --
    // those two disagree by a cent on 2184 of 4999 cent-mids from $0.02 to
    // $50, against 3 before.
    if (parsed === value) {
      setEditing(false);
      return;
    }
    if (parsed < minVal || parsed > maxVal) {
      setRejected(
        maxVal === Infinity
          ? `Must be at least ${prefix}${minVal.toFixed(decimals)}${suffix} — kept the previous value.`
          : `Must be between ${prefix}${minVal.toFixed(decimals)}${suffix} and `
            + `${prefix}${maxVal.toFixed(decimals)}${suffix} — kept the previous value.`,
      );
      setEditing(false);
      return;
    }
    // P2-20 -- rounds at THIS field's `decimals`, not always at 2.
    const scale = 10 ** decimals;
    const next = Math.round(parsed * scale) / scale;
    // A BLUR IS NOT AN EDIT. `save` runs on every blur, so clicking into a
    // field to read it and clicking away used to emit `onChange(sameValue)`.
    // That was invisible while the page inferred "did the user touch this?" by
    // comparing the reported value against the card's seed -- a no-op write
    // reported the seed, which compared equal and was discarded. Now that
    // touched-ness is tracked rather than inferred, the same no-op write MARKS
    // THE FIELD AS TOUCHED: a stray click on Premium stop posted the seeded
    // default ($3.12 = round(5.20 mid x 0.60 global, 2)) as a deliberate stop,
    // which the server re-anchored to the $4.00 live fill and stored as 78% --
    // exactly the defect the tracked flag was introduced to remove, re-entered
    // through the one path that does not go through a keystroke.
    // Skipping the no-op is also just correct for every other field.
    //
    // COMPARED BEFORE CLAMPING, AND NOW BEFORE BOUNDING. `startEdit` seeds the
    // draft from `value`, so when `value` itself sits outside [min,max] the
    // clamp alone changed it and the post-clamp guard below could not see that
    // nothing was typed -- a bare focus-and-blur then reported a deliberate
    // edit. That comparison lives above the range check now, for the same
    // reason one step further out. Round 5 added
    // 10-99%-of-mid bounds to the Premium stop field and re-opened exactly the
    // defect this guard exists to close: the seed is `round(mid x global, 2)`
    // (trade_plan.py), and the global was allowed up to 1.0 (risk_settings.py
    // `le=1.0`; 0.99 since P2-02, but a stored legacy 1.0 still loads), at
    // which point the seed IS the mid and the max is 99% of it --
    // 1951 of 2000 mids from $0.01 to $20.00 seed above the bound. Clicking the
    // field to read it and clicking away would pin a per-position stop nobody
    // chose, on a card with no way back to inheriting.
    if (next === value) {
      setEditing(false);
      return;
    }
    setRejected(null);
    onChange(next);
    setEditing(false);
  }, [draft, min, max, onChange, onRevert, decimals, value, prefix, suffix]);

  const handleKey = useCallback(
    (e: React.KeyboardEvent) => {
      if (e.key === 'Enter') save();
      if (e.key === 'Escape') setEditing(false);
    },
    [save],
  );

  const displayValue = value == null
    ? nullLabel
    : decimals === 0
      ? `${prefix}${value}${suffix}`
      : `${prefix}${value.toFixed(decimals)}${suffix}`;

  return (
    <div className={`${styles.kvRow} ${styles.kvRowEditable}`}>
      <Text size={12} tone="secondary">{label}</Text>
      {editing ? (
        <input
          // TEXT, not number, and this is load-bearing rather than cosmetic.
          //
          // `<input type="number">` applies value sanitization: `e.target.value`
          // is the EMPTY STRING for anything that is not a valid floating-point
          // literal, "132." and ".5" included. Round 8 found what that does now
          // that an empty draft means "revert to inheriting": a user with a
          // committed 132.00 who reopens the field to make it 132.50 types
          // "132." and tabs away -- the browser hands us "", the field jumps
          // back to the plan's $140.00, the touched flag clears, and the order
          // goes out at 140. A `draft.trim() === ''` check cannot tell that
          // apart from a real deletion, because they are the same string.
          //
          // With type="text" the draft is the literal keystrokes, so "132."
          // stays "132." (parseFloat gives 132) and only an actually empty
          // field reads as empty. `min`/`max`/`step` are dropped from the DOM
          // with it -- browser-native range enforcement is not what guards this
          // input anyway; `save` is, and it now reverts rather than clamps.
          type="text"
          inputMode="decimal"
          className={styles.editInput}
          value={draft}
          onChange={(e) => { typedRef.current = true; setDraft(e.target.value); }}
          onBlur={save}
          onKeyDown={handleKey}
          autoFocus
          aria-label={`Edit ${label}`}
          // The only surfacing of the clear-to-inherit gesture. A tooltip
          // rather than a line of copy or a revert button, because the card's
          // layout is governed by the schematic and the card-level edited
          // indicator is a separate, still-unbuilt decision
          // (EDITED-FLAG-2026-09-04) that this must not pre-empt.
          title={onRevert ? `Clear to go back to the plan's ${label.toLowerCase()}` : undefined}
        />
      ) : (
        <span
          className={styles.editValue}
          onClick={startEdit}
          role="button"
          tabIndex={0}
          onKeyDown={(e) => {
            if (e.key === 'Enter' || e.key === ' ') startEdit();
          }}
          aria-label={`Edit ${label}`}
        >
          {value == null
            ? <Text size={13} weight={400} tone="dim">{displayValue}</Text>
            : mono
              ? <Data size={13} weight={500} tone={tone}>{displayValue}</Data>
              : <Text size={13} weight={500}>{displayValue}</Text>}
        </span>
      )}
      {/* The refusal, announced. `aria-live="polite"` rather than an alert
          role: nothing on screen is wrong, a typed value was declined.
    *
          ROUND 10 finding 10 -- THE REGION IS ALWAYS MOUNTED, only its text
          changes. Round 9 rendered the region and its content together under
          `{rejected && …}`, which is the canonical way to get no announcement
          at all: a live region has to be in the DOM before its contents change
          for assistive tech to observe the mutation. The round-9 test used
          `findByText`, which passes either way and so could not tell
          "announced" from "rendered". Kept out of the layout when empty via
          the empty-string child rather than by unmounting. */}
      <span
        className={rejected ? styles.editRejected : styles.editRejectedEmpty}
        aria-live="polite"
      >
        {rejected ? <Text size={11} tone="caution">{rejected}</Text> : ''}
      </span>

  premiumStop: number;
  timeStopDays: number;
  targets: number[];
  contracts: number;
}

export type EditableField = keyof EditOverlay;

/** Field order here is the order the indicator's tooltip lists them in, and it
 *  follows the card top-to-bottom: entry strip, then the exit block. */
export const EDITABLE_FIELDS: readonly EditableField[] = [
  'entryLimit', 'maxFill', 'contracts', 'invalidation', 'premiumStop', 'timeStopDays', 'targets',
] as const;

/** Whether the user has changed each overlay field on the card currently on
 *  screen. Distinct from `TouchedFields` in TradeCard, which covers only the
 *  three fields a SEND path reads and is reported to the parent — this one is
 *  card-local display state and covers every field. The three they share are
 *  written in the same statements, so they cannot disagree. */
export type EditedFields = Record<EditableField, boolean>;

export const NO_EDITS: EditedFields = {
  entryLimit: false, maxFill: false, contracts: false, invalidation: false,
  premiumStop: false, timeStopDays: false, targets: false,
};

/** Labels as the card itself spells them, so the tooltip names what the user
 *  can see. "Time stop" and "Max fill" match their read-only `KV` rows. */
export const FIELD_LABELS: Record<EditableField, string> = {
  entryLimit:   'Entry limit',
  maxFill:      'Max fill',
  contracts:    'Contracts',
  invalidation: 'Invalidation',
  premiumStop:  'Premium stop',
  timeStopDays: 'Time stop',
  targets:      'Targets',
};

/** The contract count the scan plans. There is no scan-supplied size — the
 *  backend never sends one — so the plan is the card's own default, and
 *  TradeCard's `defaultOverlay` seeds from this same constant so the two
 *  cannot drift. */
export const DEFAULT_CONTRACTS = 1;

/**
 * The plan the overlay is measured against: the card's CURRENT data, not the
 * data it mounted with. That is deliberate — `mergePlan` is allowed to move
 * it, and when it does, an untouched field follows it (so nothing flags) while
 * a touched field is compared against the new plan (so the flag reflects what
 * the user would actually be overriding now).
 *
 * `contracts` IS NOT `initialContracts`, and that is the whole point.
 *
 * ROUND 1 FINDING. It was, briefly, on the reasoning the deleted `isDirty`
 * recorded: the parent seeds a shared per-symbol size, so comparing against a
 * literal 1 would flag a card the parent had sized. That reasoning belonged to
 * `isDirty`'s pure value comparison and does not survive the touched half of
 * this rule — but taking `initialContracts` as the baseline broke the field
 * outright, because of where that prop comes from.
 *
 * `step-7-trade-card/page.tsx` writes `orderContractsBySymbol` from
 * `handleEditsChange` UNCONDITIONALLY (`{ ...prev, [symbol]: overlay.contracts }`),
 * unlike the three caches beside it, which write `null` unless `meta.touched`
 * says the user typed. It then feeds that map straight back in as this very
 * prop. So the moment the user edits Contracts, the "plan" became the edit:
 * overlay 7 vs baseline 7, no difference, no badge — for the one field whose
 * count reaches a broker order. The card was silent on the edit it exists to
 * announce.
 *
 * Comparing against the constant is safe here precisely because a value alone
 * never raises the flag: a card that MOUNTS at 7 has `edited.contracts` set by
 * `restoredEdits` instead, which is truthful, since the user is the only thing
 * that ever writes a count into that map.
 */
export function planOverlay(data: TradeCardData): EditOverlay {
  return {
    entryLimit:   data.entry.limit,
    maxFill:      data.entry.maxFill,
    invalidation: data.exit.invalidation,
    premiumStop:  data.exit.premiumStop,
    timeStopDays: data.exit.timeStopDays,
    targets:      data.exit.targets.map((t) => t.targetPrice ?? t.stockPrice),
    contracts:    DEFAULT_CONTRACTS,
  };
}

function targetsDiffer(a: readonly number[], b: readonly number[]): boolean {
  if (a.length !== b.length) return true;
  return a.some((v, i) => v !== b[i]);
}

function fieldDiffers(field: EditableField, overlay: EditOverlay, plan: EditOverlay): boolean {
  if (field === 'targets') return targetsDiffer(overlay.targets, plan.targets);
  return overlay[field] !== plan[field];
}

/**
 * Which fields the user has edited AND left differing from the plan, in
 * `EDITABLE_FIELDS` order. An empty array means the card is inheriting the
 * plan everywhere and the indicator does not render.
 */
export function editedFields(
  overlay: EditOverlay,
  plan: EditOverlay,
  edited: EditedFields,
): EditableField[] {
  return EDITABLE_FIELDS.filter((f) => edited[f] && fieldDiffers(f, overlay, plan));
}

/**
 * Fold one `patch()` into the edited-field record.
 *
 * Mirrors `patch`'s own rule for `TouchedFields` and for the same reason: a
 * patch carries a partial, but any caller may re-send a value unchanged
 * (EditableKV's save-on-blur did), and a key merely being PRESENT is not the
 * user choosing it. Only a key whose value actually differs from the overlay
 * it is being applied to counts.
 *
 * Returns the identical `prev` when nothing changed, so a no-op patch cannot
 * re-render the card through this state.
 */
export function markEdited(
  prev: EditedFields,
  partial: Partial<EditOverlay>,
  current: EditOverlay,
): EditedFields {
  let next: EditedFields | null = null;
  for (const f of EDITABLE_FIELDS) {
    const incoming = partial[f];
    if (incoming === undefined || prev[f]) continue;
    const changed = f === 'targets'
      ? targetsDiffer(incoming as number[], current.targets)
      : incoming !== current[f];
    if (changed) next = { ...(next ?? prev), [f]: true };
  }
  return next ?? prev;
}

/**
