export function stopJustification(stop: {
  source: 'structural' | 'atr_widened';
  structuralPrice: number | null;
  atrFloorPrice: number;
  distanceDollar: number | null;
}): string {
  if (stop.structuralPrice == null) {
    return `No structural stop found nearby — stop set at the ATR floor of $${stop.atrFloorPrice.toFixed(2)}`;
  }
  if (stop.source === 'structural') {
    const cleared = stop.distanceDollar != null ? stop.distanceDollar.toFixed(2) : '0.00';
    return `Using structural — it already clears the ATR floor by $${cleared}, no widening needed`;
  }
  return `Structural stop $${stop.structuralPrice.toFixed(2)} was inside the ATR floor — widened to $${stop.atrFloorPrice.toFixed(2)} for a minimum-distance stop`;
}

/** FOUR explicit states per target row, not three — "outside tolerance but
 *  still short of the structural level" gets its own label rather than folding
 *  into the "beyond" warning bucket, because the two mean opposite things about
 *  the target's realism. */
export type TargetCompareState = 'none' | 'within' | 'before' | 'beyond';

export function targetCompareState(t: {
  structuralPrice: number | null;
  tpSource: 'arithmetic' | 'structural_snap';
  qualityReasons: string[];
}): TargetCompareState {
  if (t.structuralPrice == null) return 'none';
  if (t.tpSource === 'structural_snap') return 'within';
  return t.qualityReasons.includes('target_beyond_structural') ? 'beyond' : 'before';
}

export function targetCompareLabel(state: TargetCompareState): string {
  switch (state) {
    case 'none':
      return 'No structural level found ahead — nothing to compare against.';
    case 'within':
      return 'Within tolerance — snapped onto the structural level.';
    case 'before':
      return 'Outside tolerance — using arithmetic price, sits before the next structural level.';
    case 'beyond':
      return 'Target sits beyond the next real structural level.';
  }
}

const sharedStop = useMemo(() => {
  if (exitPlan && arithmeticLiveStockPrice != null) {
    return { price: exitPlan.stop.price, stockPrice: arithmeticLiveStockPrice, source: 'exit_plan' as const };
  }
  if (structuralStop) {
    return { price: structuralStop.price, stockPrice: structuralStopStockPrice ?? data.price, source: 'structural' as const };
  }
  return null;
}, [exitPlan, arithmeticLiveStockPrice, structuralStop, structuralStopStockPrice, data.price]);

const ladderRisk = overlay.entryLimit;
useEffect(() => { onRrStaleChange?.(rrStale); }, [onRrStaleChange, rrStale]);

const stockStopMoved = useMemo(() => {
  if (raceBarriers == null || firstPassage?.race == null) return false;
  // `overlay.invalidation` for the same reason `resolvedStockStop` uses it:
  // this is the guard that CLEARS a race whose barrier has moved, and it has
  // to watch the same value the race was actually run against. Reading the
  // seed here left one asymmetry with no defensible reason for it — editing
  // the Premium stop cleared the race (via the `overlay.premiumStop`
  // comparison in `raceBarriersMoved` below), editing the Invalidation did
  // not, so the card went on printing bars, medians and both risk legs
  // measured at a level no longer shown anywhere on it.
  return (sharedStop?.price ?? overlay.invalidation) !== raceBarriers.stockStop;
}, [raceBarriers, firstPassage, sharedStop, overlay.invalidation]);

const raceBarriersMoved = useMemo(() => {
  if (raceBarriers == null || firstPassage?.race == null) return false;
  return stockStopMoved || overlay.premiumStop !== raceBarriers.premiumStop;
}, [raceBarriers, firstPassage, stockStopMoved, overlay.premiumStop]);

// THE single gate on showing race numbers anywhere. It was previously spelled
// out inline for BarrierRaceCard and simply omitted from the Final
// Recommendation, so a restored estimate — `firstPassage` is seeded from the
// parent's per-contract cache at mount, and `raceBarriers` is null then, so
// nothing looked "moved" — refused to render the card and yet printed that
// same arbitrarily-old race's armed stop and dollar edge in the decision
// summary, while suppressing the un-stale invalidation fallback underneath
// it. That is the mixed-vintage hazard section 3.3 exists to prevent, landing
// in the one place on the card a number is most likely to be acted on.
// Hoisted and named so the two sites cannot drift apart again.
// Derived from STATE alone, deliberately, and not from firstPassageIsFreshRef.
// `raceBarriers` is set only on a successful estimate and cleared in exactly
// the places the ref is (the handler's entry, the contract-change effect), so
// `raceBarriers.contract === data.contract` carries everything the ref
// carried AND survives the frame between commit and that effect, which a ref
// cleared inside it cannot.
//
// Keeping both read well but made neither load-bearing: with the ref in the
// expression, deleting the contract term left all TradeCard tests green,
// because the ref still hid the restored-estimate case that was the only
// observable one. A guard no test can fail is not a guard. The ref remains
// for its other consumers.
//
// TWO SEPARATE THINGS, deliberately. `estimateIsFresh` means "the estimate on
// screen was fetched this mount, for the contract on screen"; `raceIsShowable`
// adds "and neither barrier has moved since". The card needs the first,
// because it renders the "barriers changed — re-run" copy itself and would
// otherwise be handed a prop it can never act on. Everything that prints race
// NUMBERS needs the second.
//
// RENAMED from `raceIsFresh` when TARGET-VINTAGE-2026-09-04 put the Final
// Recommendation's `firstPassage.targets` rows behind it too. The value is
// unchanged and the new name is the accurate one: `setRaceBarriers` fires on
// EVERY successful estimate, including one the backend refused to run a race
// for (`race: null` at dte < 1), and is cleared at the estimate handler's
// entry and in the contract-change effect. So it never meant "a race came
// back" — it means "an estimate did", which is precisely the vintage question
// the target rows needed answered.
// ONE term, not two. `firstPassageContext` was listed beside this and was
// implied by it: setRaceBarriers is called on the line after
// setFirstPassageContext, and both are cleared together at the handler's
// entry and in the contract-change effect, so deleting it changed no test —
// verbatim the criticism this comment levels at the ref it replaced. A guard
// no test can fail is not a guard, and two of them are not better than one.
// Display-only basis: prefer this result's server-rounded cents. The raw
// captured request can differ at a half-cent due to Python's rounding.
// A larger mismatch is not a matched basis for a dollar outcome.
const capturedMcPremium = firstPassageContext?.premium;
const echoedMcPremium = firstPassage?.race?.premiumUsed;
const hasMcEcho = firstPassage?.race != null;
const capturedMcValid = capturedMcPremium != null && Number.isFinite(capturedMcPremium) && capturedMcPremium > 0;
const echoedMcValid = echoedMcPremium != null && Number.isFinite(echoedMcPremium) && echoedMcPremium > 0;
const mcPremium = firstPassage == null ? null
  : hasMcEcho
    ? echoedMcValid && (firstPassageContext == null || (capturedMcValid && Math.abs(capturedMcPremium! - echoedMcPremium!) <= 0.005 + 1e-9))
      ? echoedMcPremium! : null
    : capturedMcValid ? Number(capturedMcPremium!.toFixed(2)) : null;
const estimateIsFresh = raceBarriers?.contract === data.contract;

const raceIsShowable = estimateIsFresh && !raceBarriersMoved;

// Phase G piece 5 — PICK-ONLY variants of the two flags above, compared
// against `prevContractRef.current` instead of the `data.contract` PROP.

 *  A boolean, not the option object, so the effect does not re-fire on every
 *  render just because `methodPickOptions` is a fresh array. */
const pickedOption = methodPick
  ? methodPickOptions.find((o) => o.method === methodPick.method) ?? null
  : null;
const pickedMethodGone = methodPick != null
  && (pickedOption == null || pickedOption.unavailable != null);

const applyMethodPickRef = useRef(applyMethodPick);
useEffect(() => { applyMethodPickRef.current = applyMethodPick; }, [applyMethodPick]);
useEffect(() => {
  // Clearing sets `methodPick` to null, which makes `pickedMethodGone` false
  // on the next render, so this cannot loop.
  if (pickedMethodGone) {
    applyMethodPickRef.current(null);
    setRecommendationInvalidated(true);
  }
}, [pickedMethodGone]);

const recommendationMethod = methodPick?.method ?? lastRunMethod;
const recommendationUnavailable = recommendationInvalidated || pickedMethodGone;

const stockBars = [
  { label: 'Trend',     value: data.stockBreakdown.trend,     detailText: trendDetailText(data.stockBreakdown.trendDetail) },
  { label: 'Pullback',  value: data.stockBreakdown.pullback,  detailText: pullbackDetailText(data.stockBreakdown.pullbackDetail) },
  { label: 'Trigger',   value: data.stockBreakdown.trigger,   detailText: triggerDetailText(data.stockBreakdown.triggerDetail) },
  { label: 'Event',     value: data.stockBreakdown.event,     detailText: eventDetailText(data.stockBreakdown.eventDetail) },
  { label: 'Volatility',value: data.stockBreakdown.volatility,detailText: volDetailText(data.stockBreakdown.volDetail) },
];

const contractBars = [
  { label: 'DTE fit', value: data.contractBreakdown.dteFit, detailText: dteDetailText(data.contractBreakdown.dteDetail) },
  { label: 'Delta', value: data.contractBreakdown.delta, detailText: deltaDetailText(data.contractBreakdown.deltaDetail) },
  { label: 'IV', value: data.contractBreakdown.ivAttractiveness, detailText: ivDetailText(data.contractBreakdown.ivDetail) },
  { label: 'Liquidity', value: data.contractBreakdown.liquidity, detailText: liquidityDetailText(data.contractBreakdown.liquidityDetail) },
  { label: 'Spread', value: data.contractBreakdown.spread, detailText: spreadDetailText(data.contractBreakdown.spreadDetail) },
];

const methodSelector = (
  <MethodPickSelector
    options={methodPickOptions}
    pick={methodPick}
    onChange={applyMethodPick}
  />
);

// contracts.exit_plan prices both targets and StopCost with req.premium.
// Use that echoed, cent-rounded calculation basis only; current quotes and
// order edits are different vintages. A legacy/mismatched cost cannot supply it.
const arithmeticCost = stopPremiumRisk(exitPlan?.stop.stopCost ?? null);
const arithmeticPremium = arithmeticCost?.basis === 'bs_today'
  && arithmeticCost.stopPrice === exitPlan?.stop.price
  ? arithmeticCost.premium : null;

// Recover result evidence with the selector's price pair. A changed row
// cannot lend new probability/model data to a recorded older target.

/** "$5.20", "-$1.20". A leading minus reads better outside the dollar sign. */
export function money(v: number): string {
  const s = `$${Math.abs(v).toFixed(2)}`;
  return v < 0 ? `-${s}` : s;
}

export function days(v: number): string {
  // The reprice horizon can be fractional once a clamp binds (0.75 x a 3-day
  // contract, or the half-day-before-expiry cap). Show a whole number when it
  // is one, and otherwise enough precision to BE the value used: at 1dp,
  // 0.75 x 21 = 15.75 printed as "15.8d", and this card's contract is that
  // every printed input is the one the arithmetic used.
  if (Number.isInteger(v)) return `${v}d`;
  return `${Number(v.toFixed(2))}d`;
}

/**
 * The four allocated weights as whole percentages. They sum to exactly 100
 * because the backend allocated them to hundredths that sum to 1.00 — this only
 * scales them, it does not round anything.
 *
 * There used to be a largest-remainder allocation HERE, over the raw shares,
 * which fixed the labels but left the edge chain three blocks below printing a
 * separately-rounded multiplier for the same outcome — the table reading
 * "Neither 49%" beside a chain reading "+ 0.48 x". Any share whose allocated
 * hundredth differs from its own 2dp rounding disagrees, which on sampled
 * sweeps of real output ran from a few percent to a fifth of rows depending on
 * the parameter mix. One allocation, done once, upstream of both.
 */
export function weightPercents(o: BarrierRaceOutcome): number[] {
  return [
    o.weightTargetFirst, o.weightStockStopFirst, o.weightPremiumStopFirst, o.weightNeither,
  ].map((w) => Math.round(w * 100));
}

/**
 * The stock-stop risk leg, with its inputs.
 *
 *   "$5.20 premium - $1.09 at the stop (repriced at 7d) = $4.11"
 *
 * The chain adds up exactly, because the backend does this arithmetic in cents
 * for that reason.
 *
 * `premium` must be the backend's own `race.premiumUsed`, not a local copy:
 * Python's round() is banker's rounding and JavaScript's toFixed() is not, so
 * on an exact half-cent the two disagree and the printed chain stops adding up.
 *
 * "repriced at Nd" is DAYS ELAPSED until the stop is reached, and it is the
 * same on all three rows — the stop leg is a property of the stop, not of the
 * target being raced against it.
 */
export function formatRaceRisk(o: BarrierRaceOutcome, premium: number): string {
  if (o.stopRepricedValue == null || o.riskStockStop == null) {
    return `${money(premium)} premium - could not reprice at the stop`;
  }
  // The horizon is named, not just numbered. It is the UNCONDITIONAL median day
  // any path reaches the stop (shown in the barriers block above), while the
  // table's "to stock stop" column is the CONDITIONAL median over stop-first
  // paths — so the two legitimately differ, and on the reference contract the
  // column reads "—" while this chain says 26d. When no path reached the stop
  // at all, this is the preset fallback and no median exists anywhere on screen.
  const basis = (() => {
    if (o.daysAnyPathReachedStop == null) {
      return ' — the preset default; no path reached the stop';
    }
    // The median is capped half a day short of expiry, so on a short contract
    // the number printed here is NOT the median: at dte=10 with a median of
    // 10, this prints 9.5 while daysAnyPathReachedStop is 10. Calling that
    // "the median" was simply false whenever the cap bound.
    if (Math.abs(o.daysAnyPathReachedStop - o.repriceDaysStockStop) > 1e-9) {
      return ` — capped just short of expiry; the median is ${days(o.daysAnyPathReachedStop)}`;
    }
    return ' — the median day any path reaches the stop';
  })();
  return (
    `${money(premium)} premium - ${money(o.stopRepricedValue)} at the stop ` +
    `(repriced at ${days(o.repriceDaysStockStop)}${basis}) = ${money(o.riskStockStop)}`
  );
}

/**
 * The stock-stop R:R, with its inputs. THE measurement on this card.
 *
 *   "$1.04 / $4.11 = 0.25x"
 *
 * Returns the em-dash form when the risk leg is not positive — possible on a
 * deep-ITM contract with a tight stop, where the option is still worth more at
 * the stop than it cost. Never render a negative or infinite ratio.
 */
export function formatRaceRR(o: BarrierRaceOutcome): string {
  // Two different states, two different sentences. Folding them together
  // printed "worth more there than it cost" for a stop that could not be
  // repriced AT ALL — directly under formatRaceRisk's "could not reprice at
  // the stop", two adjacent lines explaining the same state incompatibly.
  if (o.riskStockStop == null || o.stopRepricedValue == null) {
    return `${money(o.rewardDollar)} / could not reprice at the stop = —`;
  }
  if (o.rrStockStop == null || o.riskStockStop <= 0) {
    return `${money(o.rewardDollar)} / no risk at the stop (worth more there than it cost) = —`;
  }
  return `${money(o.rewardDollar)} / ${money(o.riskStockStop)} = ${o.rrStockStop.toFixed(2)}x`;
}

/**
 * The premium-stop R:R, labelled as the constant it is.
 *
 *   "$1.04 / $3.12 = 0.33x - equals your 20% target / 60% stop, on every contract"
 *
 * Its risk leg IS proportional to premium, so premium cancels out of the ratio
 * and it reduces to the two percentages the user typed. Shown for completeness;
 * the card must say it is not a measurement.
 */
export function formatRacePremiumRR(o: BarrierRaceOutcome): string {
  // "legs A and B", never "A / B". A slash between two dollar amounts reads as
  // a division to the one audience this card is built for — someone checking
  // the arithmetic — and on a $1.03 premium the cent-quantized legs $0.21 and
  // $0.62 divide to 0.34x, not the 0.33x this column is BY DEFINITION. The
  // dollars are inputs, not a sum to be performed.
  const legs = `legs ${money(o.rewardDollar)} and ${money(o.riskPremiumStop)}`;
  if (o.rrPremiumStop == null) {
    return `${legs} - no premium-stop risk to divide by`;
  }
  // Deliberately NOT printed as "$1.04 / $3.12 = 0.33x". Once both legs are
  // quantized to cents their quotient no longer reproduces the constant on
  // small premiums ($0.21 / $0.62 is 0.34x, $0.21 / $0.64 is 0.33x), so
  // printing an equals sign there would assert an identity that is false on
  // exactly the contracts where this column matters least. The ratio comes
  // from the definition; the dollars are shown as its inputs, not as a sum.
  // NO PERCENTAGES HERE, and the stop percentage is no longer even a parameter.
  // Printing "20% / 60% = 0.33x" renders both at 0dp while premiumStopPct is an
  // arbitrary float — the field holds a scan-time dollar amount over the
  // premium quoted now — so on a third of realistic combinations the printed
  // division does not produce the printed ratio: a $0.20 stop on a $0.70
  // premium prints "10% / 29%", which is 0.34, beside a true 0.35. Replacing
  // one unverifiable chain with another is not a fix. The stop percentage is
  // shown once, in the barriers block above, where it is not part of a sum.
  // The ratio is STATED, and the reader is no longer told to derive it from the
  // two percentages on screen. Deleting the printed division was not enough:
  // "which is your target % over your stop %" instructs the same division, and
  // the operands are both rendered at 0dp while the stop fraction is an
  // arbitrary float — a 20% target against a 0.5455 stop prints "20%" and
  // "~55%", whose quotient is 0.36, beside a true 0.37x. The block-level prose
  // under this table explains WHY the number carries no information, which is
  // the part worth saying, without attaching the claim to a specific pair of
  // rounded digits.
  return `${legs} - ${o.rrPremiumStop.toFixed(2)}x, the same on every contract`;
}

/**
 * The edge, with all four signed contributions.
 *
 *   "0.27 x $1.04 - 0.00 x $5.02 - 0.69 x $3.12 + 0.05 x -$1.57 = -$1.93  ->  -$193"
 *
 * Term order matches the outcome columns above it on the card, so the chain
 * reads in the same order as the bars.
 *
 * The fourth term is SIGNED, not a loss: a path that reached no barrier can end
 * above the premium paid. Writing it as "- p x loss" would be wrong whenever
 * that happens.
 */
export function formatRaceEdge(o: BarrierRaceOutcome, premium: number): string {
  if (o.edgePerContract == null || o.riskStockStop == null) return '—';
  const perShare = o.edgePerContract / 100;
  // A NEGATIVE stock-stop risk leg is a real state, not an error: on a deep-ITM
  // contract with a tight stop the option can still be worth more at the stop
  // than it cost. Subtracting it then ADDS to the edge, which is correct signed
  // EV but reads as an unexplained "- 0.00 x -$70.90". Print it as the gain it
  // is, and say why — the R:R column shows an em dash in the same state, and
  // nothing else on the card connects the two.
  const stopTerm = o.riskStockStop < 0
    ? ` + ${o.weightStockStopFirst.toFixed(2)} x ${money(-o.riskStockStop)} (worth more at the stop than it cost)`
    : ` - ${o.weightStockStopFirst.toFixed(2)} x ${money(o.riskStockStop)}`;
  return (
    `${o.weightTargetFirst.toFixed(2)} x ${money(o.rewardDollar)}` +
    stopTerm +
    ` - ${o.weightPremiumStopFirst.toFixed(2)} x ${money(o.riskPremiumStop)}` +
    // The fourth operand spelled out. Every other number in this chain is
    // derivable from something else on screen — $1.04 is the printed target
    // price minus the printed premium, $3.12 is the premium minus the printed
    // barrier, $5.17 has its own printed chain. `neither` is terminalMean minus
    // the premium, and terminalMean appears nowhere else on the card, so the
    // one term the card goes out of its way to explain the SIGN of was the one
    // term a user could not check.
    ` + ${o.weightNeither.toFixed(2)} x ${o.terminalMean == null
      // Not "$0.00 at expiry" — that is a number for a population that does not
      // exist. terminalMean is null exactly when no path reached expiry
      // unbarriered, in which case this weight is 0.00 and the term contributes
      // nothing; saying so beats printing a price nothing was worth.
      ? '$0.00 (no path reached expiry unbarriered)'
      : `(${money(o.terminalMean)} at expiry - ${money(premium)})`}` +
    ` = ${money(perShare)}  ->  ${money(o.edgePerContract)} per contract`
  );
}

/**
 * What to print under "How it is set" for the premium-stop barrier.
 *
 * The card used to state unconditionally that the level came "from the editable
 * field above". It often does not. The field holds a DOLLAR amount derived at
 * SCAN time (`premium x premium_stop_pct`), while the conversion divides it by
 * the premium quoted NOW — so a contract that has since fallen turns a "60%
 * stop" into a 94% one, and one that has fallen far enough makes the fraction
 * >= 1, at which point nothing is sent and the backend silently applies
 * risk_rules.yaml's own default. Saying so is the fix; the mismatch itself is
 * the field being stale, which is the user's to resolve.
 *
 * `fromField` is decided AT REQUEST TIME by the caller, from the same premium
 * the request used — not re-derived here. Re-deriving it from the backend's
 * cent-rounded `premiumUsed` disagreed with the request in the band where the
 * two straddle 1.0: a quoted premium of 2.996 against a $2.998 field made the
 * request send nothing (1.0007) while the note credited the field (0.9993).
 */
export function premiumStopSourceNote(
  appliedPct: number,
  fromField: boolean,
  dollarStop: number | null | undefined,
  premium: number,
): string {
  // "stops out after losing ~55% of premium", NOT "~55% of premium". The
  // percentage is the LOSS that fires the stop; the cell immediately beside it
  // holds the resulting LEVEL, which is the complement — a $2.75 premium with a
  // 55% stop sits at $1.25, and 55% of $2.75 is $1.51. Two numbers in one table
  // row that cannot be reconciled without silently knowing to take the
  // complement, on a card whose premise is that every term can be checked by
  // hand. The `~` fixes the precision; this fixes the sense.
  const applied = `stops out after losing ~${(appliedPct * 100).toFixed(0)}% of premium`;
  if (fromField) {
    return `${applied}, from the editable field above`;

    return `${applied}, from the editable field above`;
  }
  // ROUND 10 finding 5 -- THE TOTAL-LOSS BRANCH NOW CHECKS THAT IT IS ONE.
  //
  // Until round 9, `fromField` was false only when premiumStopPctFromDollars
  // returned undefined, which happened only when the dollar stop was at or
  // above the premium -- so "your stop is at or above the premium" followed
  // from the branch being reached at all. Round 9 gated the barrier on
  // TOUCHED-NESS (correctly: an untouched field holds the seeded global, not a
  // choice), which made `fromField` false for perfectly ordinary cards too --
  // and this branch then told users their $3.12 stop was "at or above the
  // $4.00 premium", which is simply false, on every untouched estimate.
  //
  // The condition it always relied on is now stated instead of assumed.
  if (dollarStop != null && Number.isFinite(dollarStop) && dollarStop > 0
      && Number.isFinite(premium) && premium > 0 && dollarStop >= premium) {
    return (
      `${applied} — the default. Your ${money(dollarStop)} stop is at or above the `
      + `${money(premium)} premium this estimate used, which is a total loss rather than a stop.`
    );
  }
  // Untouched: the field above is showing the inherited global rendered in
  // dollars, not a per-trade stop anyone chose, so the race used the
  // configured default. Reachable again -- before round 9 this line was dead
  // except on a degenerate seed, and after it, it was dead outright because
  // the seed is never null.
  return `${applied} — the default, because no per-trade premium stop is set above`;
}

/**
 * The card's "Premium stop" field holds a DOLLAR amount (entry x the backend's
 * premium_stop_pct). The barrier race's third barrier is expressed as a
 * FRACTION of premium, because that is what defines the option-value level
 * `premium x (1 - pct)`. Convert, or return undefined to let the backend fall
 * back to risk_rules.yaml's own premium_stop_pct.
 *
 * A dollar stop at or above the whole premium is a total loss, which makes the
 * barrier unreachable-by-definition rather than a stop — the backend rejects
 * pct >= 1 outright, so refuse it here rather than sending a 422.
 */
export function premiumStopPctFromDollars(
  dollarStop: number | null | undefined,
  premium: number,
): number | undefined {
  if (dollarStop == null || !Number.isFinite(dollarStop) || dollarStop <= 0) return undefined;
  if (!Number.isFinite(premium) || premium <= 0) return undefined;
  const pctOfPremium = dollarStop / premium;
  if (pctOfPremium <= 0 || pctOfPremium >= 1) return undefined;
  return pctOfPremium;
}

 *  3. `'stock'` is not an arbitrary default. It is the basis the position's
 *     `stop` field carries and the one STOP_REACHED actually fires on, so a
 *     trade nobody re-basised really was judged on the stock stop. That is what
 *     separates this from "a default nobody looked at wearing a radio's
 *     clothes" — the phrase §6.1 uses about pre-selecting a method, where no
 *     such truthful default exists. */
const DEFAULT_STOP_BASIS: PickedStopBasis = 'stock';

/** Match a stored pick back to the row it names.
 *
 *  BY PRICE PAIR, because that is what `MethodPick` stores. §4.1 chose prices
 *  over a row index on purpose ("a price survives an `rr_ratios` change and
 *  `exit_plan_2r` does not"), and the cost of that choice is paid right here:
 *  the selected row has to be recovered by value. Both fields must agree, not
 *  just the one that happens to be non-null, or a Monte Carlo row with a null
 *  stock price would match every other row with a null stock price.
 *
 *  Returns null when nothing matches — a pick with no row (§7.4: picking a
 *  method alone is a complete, gate-passing decision) and a pick whose row has
 *  since been recomputed to a different price both land here, and both render
 *  as "method chosen, no row highlighted" rather than as a wrong row lit up. */
function rowOfPick(rows: MethodPickRow[], pick: MethodPick | null): string | null {
  if (!pick) return null;
  if (pick.rowStockPrice == null && pick.rowOptionPrice == null) return null;
  const hit = rows.find(
    (r) => Object.is(r.rowStockPrice, pick.rowStockPrice)
        && Object.is(r.rowOptionPrice, pick.rowOptionPrice),
  );
  return hit?.key ?? null;
}

function priceText(price: number | null): string {
